		if (typeof ref == 'function') {
			// Function refs with cleanup functions: when the ref is set to
			// `null` we call the previously returned cleanup function instead
			// of invoking the ref with `null`.
			if (value === null && ref._cleanup) {
				ref._cleanup();
				ref._cleanup = undefined;
			} else {
				const cleanup = ref(value);
				if (value !== null && typeof cleanup == 'function') {
					ref._cleanup = cleanup;
				}
			}
		} else {
			ref.current = value;
		}
	} catch (e) {
		this._hooks._catchError(e, vnode);
	}
}

